export function readSellerLocale(value: string | null | undefined): SellerLocale {
  return sellerLocales.includes(value as SellerLocale) ? value as SellerLocale : "en";
}

export function translateSeller(text: string, locale: SellerLocale, vars?: Record<string, string | number>): string {
  const template = locale === "en" ? text : messages[text]?.[sellerLocales.indexOf(locale) - 1] ?? text;
  return vars ? template.replace(/\{(\w+)\}/g, (_match, key: string) => String(vars[key] ?? `{${key}}`)) : template;
}

export function setSellerLocale(value: SellerLocale) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(SELLER_LOCALE_KEY, value);
  window.dispatchEvent(new Event("seller-locale-updated"));
}
